  const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

  await page.setContent(htmlContent, { waitUntil: 'load' });

  // Inject axe-core
  const axeCorePath = path.join(__dirname, 'node_modules/axe-core/axe.min.js');
  await page.addScriptTag({ path: axeCorePath });

  // Run axe
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  // Separate WCAG violations from best-practice
  const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bpViolations = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log('=== ACCESSIBILITY TEST RESULTS ===\n');

  if (wcagViolations.length === 0) {
    console.log('✓ WCAG 2.2 AA VIOLATIONS: NONE (Pass)\n');
  } else {
    console.log(`✗ WCAG 2.2 AA VIOLATIONS: ${wcagViolations.length}\n`);
    wcagViolations.forEach(v => {
      console.log(`[${v.id}] ${v.impact?.toUpperCase()}`);
      console.log(`   Description: ${v.description}`);
      console.log(`   Targets: ${v.nodes.map(n => n.target.join(' > ')).join(', ')}`);
      console.log();
    });
  }

  if (bpViolations.length > 0) {
    console.log(`⚠ BEST-PRACTICE VIOLATIONS: ${bpViolations.length}\n`);
    bpViolations.forEach(v => {
      console.log(`[${v.id}]`);
      console.log(`   Description: ${v.description}`);
      console.log(`   Targets: ${v.nodes.map(n => n.target.join(' > ')).join(', ')}`);
      console.log();
    });
  } else {
    console.log('✓ BEST-PRACTICE VIOLATIONS: NONE\n');
  }

  // Return test result
  return wcagViolations.length === 0 ? 0 : 1;
}

runAccessibilityTests().then(code => process.exit(code));

