        /* Deals Section */
        .deals-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: var(--space-lg);
        }

        .deal-card {
            background: linear-gradient(135deg, var(--color-accent-alert) 0%, var(--color-bg-light) 100%);
            border-radius: var(--radius);
            padding: var(--space-lg);
            position: relative;
            overflow: hidden;
            box-shadow: var(--shadow-md);
            transition: transform 0.3s;
        }

        .deal-card:hover {
            transform: scale(1.02);
        }

        .deal-card:focus-within {
            outline: 2px solid var(--color-primary);
            outline-offset: -2px;
        }

        .deal-badge {
            position: absolute;
            top: var(--space-md);
            right: var(--space-md);
            background-color: var(--color-accent-alert);
            color: white;
            padding: var(--space-xs) var(--space-md);
            border-radius: var(--radius);
            font-weight: 700;
            font-size: 1.1rem;
        }

        .deal-content {
            position: relative;
            z-index: 1;
        }

        .deal-title {
            font-size: 1.5rem;
            font-weight: 700;
            margin-bottom: var(--space-md);
            color: var(--color-secondary);
        }

        .deal-description {
            color: var(--color-text-secondary);
            margin-bottom: var(--space-lg);
        }

        .deal-btn {
            background-color: var(--color-primary);
            color: var(--color-bg-dark);
            padding: var(--space-md) var(--space-xl);
            border: none;
            border-radius: var(--radius);
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s;
        }

        .deal-btn:hover {
            background-color: var(--color-secondary);
        }

        .deal-btn:focus {
            outline: 2px solid var(--color-bg-dark);
            outline-offset: 2px;
        }

        /* Editorial Section */
        .editorial-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: var(--space-lg);
        }

        .article-card {
            background-color: var(--color-bg-light);
            border-radius: var(--radius);
            overflow: hidden;
            box-shadow: var(--shadow-sm);
            transition: transform 0.3s;
            display: flex;
            flex-direction: column;
        }

        .article-card:hover {
            transform: translateY(-4px);
