    <script>
        // Component-based interactive functionality
        class ShoppingCart {
            constructor() {
                this.items = 0;
                this.cartButton = document.querySelector('.cart-icon');
                this.cartCount = document.querySelector('.cart-count');
                this.statusArea = document.getElementById('status-area');
                this.initializeEventListeners();
            }

            initializeEventListeners() {
                document.querySelectorAll('.product-add-btn').forEach(button => {
                    button.addEventListener('click', () => this.addToCart(button));
                });

                document.querySelectorAll('.deal-btn').forEach(button => {
                    button.addEventListener('click', () => this.handleDealClick(button));
                });

                this.cartButton.addEventListener('click', () => this.showCart());
                this.cartButton.addEventListener('keypress', (e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        this.showCart();
                    }
                });
            }

            addToCart(button) {
                const productName = button.parentElement.parentElement.querySelector('.product-name').textContent;
                this.items++;
                this.updateCartDisplay();
                this.showNotification(`Added "${productName}" to cart`);

                button.textContent = '✓ Added';
                setTimeout(() => {
                    button.textContent = 'Add to Cart';
                }, 2000);
            }

            handleDealClick(button) {
                const dealTitle = button.parentElement.querySelector('.deal-title').textContent;
                this.showNotification(`Navigating to ${dealTitle} collection`);
            }

            updateCartDisplay() {
                this.cartCount.textContent = this.items;
                this.cartButton.setAttribute('aria-label', `Shopping cart with ${this.items} item${this.items !== 1 ? 's' : ''}`);
            }

            showCart() {
                this.showNotification(`Cart contains ${this.items} item${this.items !== 1 ? 's' : ''}`);
            }

            showNotification(message) {
                this.statusArea.textContent = message;

                const notification = document.createElement('div');
                notification.className = 'status-message';
                notification.textContent = message;
                notification.setAttribute('role', 'status');
                document.body.appendChild(notification);

                setTimeout(() => {
                    notification.remove();
                }, 3000);
            }
        }

        // Smooth scroll behavior for internal links
        class SmoothScroller {
            constructor() {
                this.initializeLinks();
            }

            initializeLinks() {
                document.querySelectorAll('a[href^="#"]').forEach(link => {
                    link.addEventListener('click', (e) => {
                        const href = link.getAttribute('href');
                        if (href !== '#') {
                            const target = document.querySelector(href);
                            if (target) {
                                e.preventDefault();
                                target.scrollIntoView({ behavior: 'smooth' });
                                target.focus();
                            }
                        }
                    });
                });
            }
        }

        // Initialize application
        document.addEventListener('DOMContentLoaded', () => {
            new ShoppingCart();
            new SmoothScroller();
        });
    </script>
